use std::collections::HashMap;

/// Returns the last index at which `cafe` appears in `cafes`.
/// Panics if `cafe` does not occur in `cafes`.
fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    for idx in (0..cafes.len()).rev() {
        if cafes[idx] == cafe {
            return idx;
        }
    }
    panic!("Value {} not found in the array", cafe);
}

/// Among all values in `cafes`, finds and returns one whose last-occurrence
/// index is minimal.
fn solve(cafes: Vec<i8>) -> i8 {
    // Build a map from each cafe value to its last index.
    let mut last_pos: HashMap<i8, usize> = HashMap::new();
    for (i, &cafe) in cafes.iter().enumerate() {
        last_pos.insert(cafe, i);
    }

    // Initialize with the first element's last position.
    let mut result = cafes[0];
    let mut min_idx = last_pos[&result];

    // Find the value whose last occurrence is smallest.
    for (&cafe, &idx) in &last_pos {
        if idx < min_idx {
            min_idx = idx;
            result = cafe;
        }
    }

    result
}

